function assertJSONSafe(value,depth=0){if(depth>15)throw Error('ข้อมูลซ้อนลึกเกินไป');if(typeof value==='number'&&!Number.isFinite(value))throw Error('ตัวเลขไม่ถูกต้อง');if(Array.isArray(value)){if(value.length>10000)throw Error('รายการยาวเกินไป');value.forEach(x=>assertJSONSafe(x,depth+1));}else if(value&&typeof value==='object'){for(const [key,v] of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(key))throw Error('ชื่อช่องไม่อนุญาต');assertJSONSafe(v,depth+1);}}}
