function fieldHelp(kind,key){const help=ContentSchema.help?.[kind]?.[key];if(!help)return '';const parts=typeof help==='string'?help:Object.entries(help).map(([k,v])=>k+': '+v).join('\n');return `<details class="field-help"><summary>คำอธิบายจากเกมเก่า</summary><p>${escapeHTML(parts)}</p></details>`;}
function fieldSummary(field,value){if(value===undefined||value===null||value==='')return '—';if(field.type==='boolean')return value?'ใช่':'ไม่ใช่';if(['reference','lootPicker'].includes(field.type)){const refs=R.records(DB);return (Array.isArray(value)?value:[]).map(v=>{const row=refs.find(x=>x.id===v||x.name===v);return row?.displayName||row?.name||v;}).join(', ')||'—';}if(Array.isArray(value))return value.map(x=>typeof x==='object'?(x.name?x.name+' · '+x.grade:x.key+': '+x.value):x).join(', ')||'—';return String(value);}
